CREATE TABLE users (
        id            INTEGER PRIMARY KEY AUTOINCREMENT,
        username      TEXT    UNIQUE NOT NULL,
        display_name  TEXT    NOT NULL,
        password_hash TEXT    NOT NULL,
        avatar_color  TEXT    NOT NULL DEFAULT '#007AFF',
        role          TEXT    NOT NULL DEFAULT 'member'
                              CHECK(role IN ('admin', 'member')),
        created_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      , family_role TEXT NOT NULL DEFAULT 'other'
        CHECK(family_role IN ('dad', 'mom', 'parent', 'child', 'grandparent', 'relative', 'other')), avatar_data TEXT, oidc_sub      TEXT, oidc_provider TEXT, calendar_feed_token TEXT, calendar_feed_show_assignees INTEGER NOT NULL DEFAULT 0, inventory_deadlines_feed_token TEXT, onboarding_version INTEGER NOT NULL DEFAULT 0, changelog_seen_version TEXT, changelog_seen_latest  TEXT, cycle_feed_token TEXT, schedule_feed_token TEXT, schedule_reminder_offset_minutes INTEGER, schedule_weekly_hours INTEGER, waste_feed_token TEXT, waste_feed_type_ids TEXT, schedule_overtime_enabled INTEGER, deactivated_at TEXT, sort_order INTEGER, birthday_feed_token TEXT, calendar_feed_include_birthdays INTEGER NOT NULL DEFAULT 1
        CHECK(calendar_feed_include_birthdays IN (0, 1)), avatar_key TEXT);
CREATE TABLE shopping_lists (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        name       TEXT    NOT NULL,
        created_by INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      );
CREATE TABLE meals (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        date       TEXT    NOT NULL,
        meal_type  TEXT    NOT NULL
                           CHECK(meal_type IN ('breakfast', 'lunch', 'dinner', 'snack')),
        title      TEXT    NOT NULL,
        notes      TEXT,
        created_by INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      , recipe_url TEXT, recipe_id INTEGER REFERENCES recipes(id) ON DELETE SET NULL, recurrence_template_id INTEGER REFERENCES meal_recurrence_templates(id) ON DELETE SET NULL, cook_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE shopping_items (
        id              INTEGER PRIMARY KEY AUTOINCREMENT,
        list_id         INTEGER NOT NULL REFERENCES shopping_lists(id) ON DELETE CASCADE,
        name            TEXT    NOT NULL,
        quantity        TEXT,
        category        TEXT    NOT NULL DEFAULT 'Sonstiges',
        is_checked      INTEGER NOT NULL DEFAULT 0,
        added_from_meal INTEGER REFERENCES meals(id) ON DELETE SET NULL,
        created_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      , external_uid        TEXT, external_source     TEXT NOT NULL DEFAULT 'local', external_account_id INTEGER, notes TEXT, url   TEXT, external_object_url TEXT, outbound_dirty      INTEGER NOT NULL DEFAULT 0, outbound_attempts   INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, price_cents INTEGER, store_id INTEGER REFERENCES shopping_stores(id) ON DELETE SET NULL, outbound_move INTEGER NOT NULL DEFAULT 0, outbound_move_attempts INTEGER NOT NULL DEFAULT 0, outbound_move_since TEXT, outbound_move_by INTEGER REFERENCES users(id) ON DELETE SET NULL, seen_on_server INTEGER NOT NULL DEFAULT 0);
CREATE TABLE meal_ingredients (
        id               INTEGER PRIMARY KEY AUTOINCREMENT,
        meal_id          INTEGER NOT NULL REFERENCES meals(id) ON DELETE CASCADE,
        name             TEXT    NOT NULL,
        quantity         TEXT,
        on_shopping_list INTEGER NOT NULL DEFAULT 0,
        created_at       TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at       TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      , category TEXT NOT NULL DEFAULT 'Sonstiges');
CREATE TABLE notes (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        title      TEXT,
        content    TEXT    NOT NULL,
        color      TEXT    NOT NULL DEFAULT '#FFEB3B',
        pinned     INTEGER NOT NULL DEFAULT 0,
        created_by INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      , visibility TEXT NOT NULL DEFAULT 'all'
        CHECK (visibility IN ('all', 'private')), locked INTEGER NOT NULL DEFAULT 0
        CHECK (locked IN (0, 1)));
CREATE TABLE contacts (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        name       TEXT    NOT NULL,
        category   TEXT    NOT NULL DEFAULT 'Sonstiges',
        phone      TEXT,
        email      TEXT,
        address    TEXT,
        notes      TEXT,
        created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      , family_user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, organization TEXT, job_title TEXT, birthday TEXT, website TEXT, photo TEXT, nickname TEXT, carddav_account_id INTEGER
