        CHECK (carddav_origin IN ('remote', 'merged')), first_name TEXT, last_name TEXT, middle_name TEXT, name_prefix TEXT, name_suffix TEXT, birthday_year_unknown INTEGER NOT NULL DEFAULT 0 CHECK(birthday_year_unknown IN (0, 1)));
