                               CHECK(target_module IN ('tasks', 'shopping')),
        target_list_id INTEGER REFERENCES shopping_lists(id) ON DELETE SET NULL,
        enabled        INTEGER NOT NULL DEFAULT 0,
        created_at     TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')), writable INTEGER,
        UNIQUE(account_id, list_url)
      );
CREATE INDEX idx_caldav_reminder_selection_enabled
        ON caldav_reminder_selection(account_id, enabled);
CREATE INDEX idx_shopping_items_external
        ON shopping_items(external_source, external_account_id, external_uid);
CREATE TABLE google_calendar_selection (
        calendar_id  TEXT PRIMARY KEY,
        name         TEXT NOT NULL,
        color        TEXT,
        enabled      INTEGER NOT NULL DEFAULT 1,
        sync_token   TEXT,
        last_sync    TEXT
      );
CREATE INDEX idx_google_selection_enabled
        ON google_calendar_selection(enabled);
CREATE TABLE holiday_cache (
        id          INTEGER PRIMARY KEY AUTOINCREMENT,
        type        TEXT    NOT NULL CHECK(type IN ('public', 'school')),
        country     TEXT    NOT NULL,
        subdivision TEXT,
        start_date  TEXT    NOT NULL,
        end_date    TEXT    NOT NULL,
        name        TEXT    NOT NULL,
        year        INTEGER NOT NULL
      , group_code TEXT);
CREATE INDEX idx_holiday_cache_dates
        ON holiday_cache(start_date, end_date);
CREATE INDEX idx_holiday_cache_lookup
        ON holiday_cache(type, country, subdivision, year);
CREATE TABLE "dms_accounts" (
          id          INTEGER PRIMARY KEY AUTOINCREMENT,
          provider    TEXT    NOT NULL DEFAULT 'paperless'
                                CHECK(provider IN ('paperless', 'papra')),
          name        TEXT    NOT NULL,
          base_url    TEXT    NOT NULL,
          org_id      TEXT    NOT NULL DEFAULT '',
          api_token   TEXT    NOT NULL,
          created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
          last_check  TEXT,
          UNIQUE(base_url, org_id)
        );
CREATE TABLE push_subscriptions (
          id           INTEGER PRIMARY KEY AUTOINCREMENT,
          user_id      INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
          endpoint     TEXT    NOT NULL UNIQUE,
          p256dh       TEXT    NOT NULL,
          auth         TEXT    NOT NULL,
          user_agent   TEXT,
          created_at   TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
          last_used_at TEXT
        , wall_paused_at TEXT);
CREATE INDEX idx_push_subs_user ON push_subscriptions(user_id);
CREATE TABLE password_resets (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        token_hash TEXT    NOT NULL,
        expires_at INTEGER NOT NULL,
        created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
      );
CREATE UNIQUE INDEX idx_password_resets_hash ON password_resets(token_hash);
CREATE INDEX idx_password_resets_user ON password_resets(user_id);
CREATE TABLE subscription_categories (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        name       TEXT    NOT NULL COLLATE NOCASE UNIQUE,
        color      TEXT    NOT NULL DEFAULT '#0F766E',
        sort_order INTEGER NOT NULL DEFAULT 0,
        created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      , budget_subcategory_key TEXT, label_key TEXT);
CREATE TABLE subscription_payment_methods (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        name       TEXT    NOT NULL COLLATE NOCASE UNIQUE,
        sort_order INTEGER NOT NULL DEFAULT 0,
        created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      , label_key TEXT);
CREATE TABLE budget_subscriptions (
        id                INTEGER PRIMARY KEY AUTOINCREMENT,
        name              TEXT    NOT NULL,
        description       TEXT,
        amount            REAL    NOT NULL CHECK(amount >= 0),
        currency          TEXT    NOT NULL,
        billing_cycle     TEXT    NOT NULL CHECK(billing_cycle IN ('daily', 'weekly', 'monthly', 'yearly')),
        cycle_interval    INTEGER NOT NULL DEFAULT 1 CHECK(cycle_interval BETWEEN 1 AND 365),
        next_payment_date TEXT    NOT NULL,
        category_id       INTEGER REFERENCES subscription_categories(id) ON DELETE SET NULL,
        payment_method_id INTEGER REFERENCES subscription_payment_methods(id) ON DELETE SET NULL,
        reminder_days     INTEGER NOT NULL DEFAULT 3 CHECK(reminder_days BETWEEN 0 AND 365),
        enabled           INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0, 1)),
        website_url       TEXT,
        logo_data         TEXT,
        brand_color       TEXT,
        notes             TEXT,
        created_by        INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        created_at        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      , budget_entry_id INTEGER
        REFERENCES budget_entries(id) ON DELETE SET NULL, owner_id INTEGER
        REFERENCES users(id) ON DELETE SET NULL, visibility TEXT NOT NULL DEFAULT 'shared'
        CHECK (visibility IN ('private', 'shared')), end_type TEXT NOT NULL DEFAULT 'never'
        CHECK(end_type IN ('never', 'on_date', 'after_count')), end_date TEXT, occurrence_count INTEGER, occurrences_done INTEGER NOT NULL DEFAULT 0, completed_at TEXT, account_username TEXT, reminder_enabled INTEGER NOT NULL DEFAULT 1
        CHECK(reminder_enabled IN (0,1)), account_id INTEGER
        REFERENCES budget_accounts(id) ON DELETE SET NULL);
CREATE TABLE subscription_settings (
        id             INTEGER PRIMARY KEY CHECK(id = 1),
        monthly_budget REAL    NOT NULL DEFAULT 0 CHECK(monthly_budget >= 0),
        base_currency  TEXT    NOT NULL DEFAULT 'EUR',
        updated_at     TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      );
CREATE TABLE subscription_exchange_rates (
        base_currency TEXT NOT NULL,
        quote_currency TEXT NOT NULL,
        rate          REAL NOT NULL CHECK(rate > 0),
        fetched_at    TEXT NOT NULL,
        PRIMARY KEY(base_currency, quote_currency)
      );
CREATE INDEX idx_budget_subscriptions_next_payment
        ON budget_subscriptions(enabled, next_payment_date);
CREATE INDEX idx_budget_subscriptions_category
        ON budget_subscriptions(category_id);
CREATE INDEX idx_budget_subscriptions_payment_method
        ON budget_subscriptions(payment_method_id);
CREATE INDEX idx_budget_subscriptions_budget_entry
        ON budget_subscriptions(budget_entry_id);
