        ON subscription_categories(budget_subcategory_key)
        WHERE budget_subcategory_key IS NOT NULL;
CREATE TABLE notification_channels (
        id              INTEGER PRIMARY KEY AUTOINCREMENT,
        provider        TEXT    NOT NULL,
        name            TEXT    NOT NULL,
        enabled         INTEGER NOT NULL DEFAULT 0,
        scope           TEXT    NOT NULL DEFAULT 'household',
        user_id         INTEGER REFERENCES users(id) ON DELETE CASCADE,
        config_json     TEXT    NOT NULL DEFAULT '{}',
        secret_json     TEXT    NOT NULL DEFAULT '{}',
        last_test_at    TEXT,
        last_success_at TEXT,
        last_error      TEXT,
        created_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      );
CREATE INDEX idx_notification_channels_provider
        ON notification_channels(provider);
CREATE INDEX idx_notification_channels_enabled
        ON notification_channels(enabled);
CREATE INDEX idx_notification_channels_user
        ON notification_channels(user_id);
CREATE TABLE notification_deliveries (
        id              INTEGER PRIMARY KEY AUTOINCREMENT,
        reminder_id     INTEGER NOT NULL REFERENCES reminders(id) ON DELETE CASCADE,
        provider        TEXT    NOT NULL,
        channel_id      INTEGER REFERENCES notification_channels(id) ON DELETE SET NULL,
        target_key      TEXT    NOT NULL,
        status          TEXT    NOT NULL DEFAULT 'pending'
                                  CHECK(status IN ('pending', 'sent', 'failed', 'skipped')),
        attempt_count   INTEGER NOT NULL DEFAULT 0,
        next_attempt_at TEXT,
        last_attempt_at TEXT,
        sent_at         TEXT,
        error           TEXT,
        created_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        UNIQUE(reminder_id, provider, target_key)
      );
CREATE INDEX idx_notification_deliveries_reminder
        ON notification_deliveries(reminder_id);
CREATE INDEX idx_notification_deliveries_retry
        ON notification_deliveries(status, next_attempt_at);
CREATE UNIQUE INDEX idx_users_calendar_feed_token
        ON users(calendar_feed_token)
        WHERE calendar_feed_token IS NOT NULL;
CREATE TABLE meal_recurrence_templates (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        start_date TEXT    NOT NULL,
        weekday    INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6),
        meal_type  TEXT    NOT NULL
                           CHECK(meal_type IN ('breakfast', 'lunch', 'dinner', 'snack')),
        title      TEXT    NOT NULL,
        notes      TEXT,
        recipe_url TEXT,
        recipe_id  INTEGER REFERENCES recipes(id) ON DELETE SET NULL,
        created_by INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      , end_date TEXT, cook_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE meal_recurrence_ingredients (
        id          INTEGER PRIMARY KEY AUTOINCREMENT,
        template_id INTEGER NOT NULL REFERENCES meal_recurrence_templates(id) ON DELETE CASCADE,
        name        TEXT    NOT NULL,
        quantity    TEXT,
        category    TEXT    NOT NULL DEFAULT 'Sonstiges',
        created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      );
CREATE TABLE meal_recurrence_exceptions (
        template_id INTEGER NOT NULL REFERENCES meal_recurrence_templates(id) ON DELETE CASCADE,
        date        TEXT    NOT NULL,
        created_by  INTEGER REFERENCES users(id) ON DELETE SET NULL,
        created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        PRIMARY KEY (template_id, date)
      );
CREATE INDEX idx_meal_recurrence_templates_weekday
        ON meal_recurrence_templates(weekday, start_date);
CREATE INDEX idx_meal_recurrence_ingredients_template
        ON meal_recurrence_ingredients(template_id);
CREATE INDEX idx_meals_recurrence_template
        ON meals(recurrence_template_id);
CREATE UNIQUE INDEX idx_meals_recurrence_occurrence
        ON meals(recurrence_template_id, date)
        WHERE recurrence_template_id IS NOT NULL;
CREATE TABLE health_vitals (
        id          INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id     INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        type        TEXT    NOT NULL,
        value_num   REAL,
        value_num2  REAL,
        value_num3  REAL,
        unit        TEXT,
        measured_at TEXT    NOT NULL,
        note        TEXT,
        visibility  TEXT    NOT NULL DEFAULT 'private'
                            CHECK(visibility IN ('private', 'family')),
        created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      );
CREATE TABLE medications (
        id               INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id          INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        name             TEXT    NOT NULL,
        dosage_text      TEXT,
        form             TEXT,
        active           INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0, 1)),
        prn              INTEGER NOT NULL DEFAULT 0 CHECK(prn IN (0, 1)),
        stock_qty        REAL,
        stock_unit       TEXT,
        refill_threshold REAL,
        note             TEXT,
        visibility       TEXT    NOT NULL DEFAULT 'private'
                                 CHECK(visibility IN ('private', 'family')),
        created_at       TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at       TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      , min_interval_hours REAL, prn_dose_qty REAL);
CREATE TABLE medication_schedules (
        id            INTEGER PRIMARY KEY AUTOINCREMENT,
        medication_id INTEGER NOT NULL REFERENCES medications(id) ON DELETE CASCADE,
        time_of_day   TEXT    NOT NULL,
        days_mask     INTEGER CHECK(days_mask IS NULL OR (days_mask BETWEEN 0 AND 127)),
        dose_qty      REAL,
        start_date    TEXT,
        end_date      TEXT,
        active        INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0, 1)),
        created_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      );
CREATE TABLE medication_logs (
        id            INTEGER PRIMARY KEY AUTOINCREMENT,
        medication_id INTEGER NOT NULL REFERENCES medications(id) ON DELETE CASCADE,
        schedule_id   INTEGER REFERENCES medication_schedules(id) ON DELETE SET NULL,
        scheduled_at  TEXT,
        status        TEXT    NOT NULL DEFAULT 'pending'
                              CHECK(status IN ('taken', 'skipped', 'pending')),
        taken_at      TEXT,
        dose_qty      REAL,
        note          TEXT,
        created_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      );
CREATE TABLE health_lab_reports (
        id          INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id     INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        report_date TEXT    NOT NULL,
        lab_name    TEXT,
        note        TEXT,
        visibility  TEXT    NOT NULL DEFAULT 'private'
                            CHECK(visibility IN ('private', 'family')),
        created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      );
CREATE TABLE health_lab_results (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        report_id  INTEGER NOT NULL REFERENCES health_lab_reports(id) ON DELETE CASCADE,
        analyte    TEXT    NOT NULL,
