        ON health_lab_reports(user_id, report_date);
CREATE INDEX idx_health_lab_results_report
        ON health_lab_results(report_id);
CREATE INDEX idx_medications_user
        ON medications(user_id);
CREATE INDEX idx_medication_logs_med_scheduled
        ON medication_logs(medication_id, scheduled_at);
CREATE INDEX idx_medication_schedules_med_active
        ON medication_schedules(medication_id, active);
CREATE TABLE reward_participants (
        user_id    INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
        enabled    INTEGER NOT NULL DEFAULT 1,
        created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      );
CREATE TABLE reward_catalog (
        id          INTEGER PRIMARY KEY AUTOINCREMENT,
        name        TEXT    NOT NULL,
        cost        INTEGER NOT NULL,
        icon        TEXT,
        description TEXT,
        is_active   INTEGER NOT NULL DEFAULT 1,
        sort_order  INTEGER NOT NULL DEFAULT 0,
        created_by  INTEGER REFERENCES users(id) ON DELETE SET NULL,
        created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      , quantity INTEGER);
CREATE TABLE reward_redemptions (
        id           INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id      INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        catalog_id   INTEGER REFERENCES reward_catalog(id) ON DELETE SET NULL,
        reward_name  TEXT    NOT NULL,
        reward_icon  TEXT,
        cost         INTEGER NOT NULL,
        status       TEXT    NOT NULL DEFAULT 'pending'
                             CHECK(status IN ('pending', 'fulfilled', 'rejected', 'cancelled')),
        note         TEXT,
        requested_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
        decided_by   INTEGER REFERENCES users(id) ON DELETE SET NULL,
        decided_at   TEXT,
        created_at   TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at   TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      , decision_reason TEXT, kind TEXT NOT NULL DEFAULT 'reward'
        CHECK(kind IN ('reward', 'withdrawal', 'deposit')), currency TEXT
        CHECK((kind = 'reward') = (currency IS NULL)));
CREATE TABLE reward_ledger (
        id            INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id       INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        delta         INTEGER NOT NULL,
        type          TEXT    NOT NULL
                              CHECK(type IN ('earn', 'bonus', 'redeem', 'adjust', 'reversal')),
        reason        TEXT,
        task_id       INTEGER REFERENCES tasks(id) ON DELETE SET NULL,
        redemption_id INTEGER REFERENCES reward_redemptions(id) ON DELETE SET NULL,
        created_by    INTEGER REFERENCES users(id) ON DELETE SET NULL,
        created_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      , series_id INTEGER, reverses_id INTEGER, unit TEXT NOT NULL DEFAULT 'points'
        CHECK(unit IN ('points', 'money')), allowance_date TEXT, currency TEXT
        CHECK((unit = 'money') = (currency IS NOT NULL)), decay_days INTEGER, base_points INTEGER);
CREATE INDEX idx_reward_ledger_user ON reward_ledger(user_id);
CREATE INDEX idx_reward_ledger_redemption ON reward_ledger(redemption_id);
CREATE INDEX idx_reward_redemptions_status ON reward_redemptions(status);
CREATE TABLE cycle_periods (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        start_date TEXT    NOT NULL,
        end_date   TEXT,
        note       TEXT,
        visibility TEXT    NOT NULL DEFAULT 'private'
                           CHECK(visibility IN ('private', 'family')),
        created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      );
CREATE TABLE cycle_day_logs (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        log_date   TEXT    NOT NULL,
        flow       TEXT    CHECK(flow IS NULL OR flow IN ('spotting', 'light', 'medium', 'heavy')),
        symptoms   TEXT,
        mood       TEXT,
        note       TEXT,
        visibility TEXT    NOT NULL DEFAULT 'private'
                           CHECK(visibility IN ('private', 'family')),
        created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')), basal_temp REAL, basal_temp_unit TEXT, cervix_mucus TEXT, lh_test TEXT, pregnancy_test TEXT, intimacy TEXT,
        UNIQUE(user_id, log_date)
      );
CREATE TABLE cycle_settings (
        user_id           INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
        cycle_length_avg  INTEGER,
        period_length_avg INTEGER,
        luteal_length     INTEGER NOT NULL DEFAULT 14,
        track_fertility   INTEGER NOT NULL DEFAULT 1 CHECK(track_fertility IN (0, 1)),
        created_at        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      , pregnancy_mode INTEGER NOT NULL DEFAULT 0
        CHECK(pregnancy_mode IN (0, 1)), pregnancy_due_date TEXT, default_visibility TEXT NOT NULL DEFAULT 'private'
        CHECK(default_visibility IN ('private', 'family')), remind_period_days_before INTEGER, remind_log_daily INTEGER NOT NULL DEFAULT 0 CHECK(remind_log_daily IN (0, 1)), contraception TEXT, perimenopause_mode INTEGER NOT NULL DEFAULT 0
        CHECK(perimenopause_mode IN (0, 1)), show_pms INTEGER NOT NULL DEFAULT 1
        CHECK(show_pms IN (0, 1)), notify_partner_user_id INTEGER
        REFERENCES users(id) ON DELETE SET NULL, notify_partner_days_before INTEGER);
CREATE INDEX idx_cycle_periods_user_start
        ON cycle_periods(user_id, start_date);
CREATE INDEX idx_cycle_day_logs_user_date
        ON cycle_day_logs(user_id, log_date);
