CREATE INDEX idx_family_documents_dms        ON family_documents(dms_account_id);
CREATE TABLE "budget_loans" (
        id                INTEGER PRIMARY KEY AUTOINCREMENT,
        title             TEXT    NOT NULL,
        borrower          TEXT    NOT NULL,
        total_amount      REAL    NOT NULL CHECK(total_amount > 0),
        installment_count INTEGER NOT NULL CHECK(installment_count > 0),
        start_month       TEXT    NOT NULL,
        notes             TEXT,
        status            TEXT    NOT NULL DEFAULT 'active'
                                  CHECK(status IN ('active', 'paid')),
        created_by        INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        created_at        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        owner_id          INTEGER REFERENCES users(id) ON DELETE SET NULL,
        visibility        TEXT    NOT NULL DEFAULT 'shared'
                                  CHECK (visibility IN ('private', 'shared')),
        interest_mode     TEXT    NOT NULL DEFAULT 'none'
                                  CHECK(interest_mode IN ('none', 'fixed', 'variable', 'fixed_then_variable')),
        principal              REAL,
        fixed_rate             REAL,
        initial_repayment_rate REAL,
        fixed_period_months    INTEGER,
        followup_rate          REAL
      , currency TEXT, exchange_rate REAL NOT NULL DEFAULT 1, direction TEXT NOT NULL DEFAULT 'lent', account_id INTEGER REFERENCES budget_accounts(id) ON DELETE SET NULL, due_day INTEGER
        CHECK (due_day IS NULL OR (typeof(due_day) = 'integer' AND due_day BETWEEN 1 AND 31)));
CREATE INDEX idx_budget_loans_status ON budget_loans(status);
CREATE INDEX idx_budget_loans_start_month ON budget_loans(start_month);
CREATE INDEX idx_budget_loans_owner ON budget_loans(owner_id);
