CREATE TABLE "tasks" (
        id                  INTEGER PRIMARY KEY AUTOINCREMENT,
        title               TEXT    NOT NULL,
        description         TEXT,
        category            TEXT    NOT NULL DEFAULT 'misc',
        priority            TEXT    NOT NULL DEFAULT 'none'
                                    CHECK(priority IN ('none', 'low', 'medium', 'high', 'urgent')),
        status              TEXT    NOT NULL DEFAULT 'open'
                                    CHECK(status IN ('open', 'in_progress', 'done', 'archived')),
        due_date            TEXT,
        due_time            TEXT,
        assigned_to         INTEGER REFERENCES users(id) ON DELETE SET NULL,
        created_by          INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        is_recurring        INTEGER NOT NULL DEFAULT 0,
        recurrence_rule     TEXT,
        parent_task_id      INTEGER REFERENCES tasks(id) ON DELETE CASCADE,
        created_at          TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at          TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        start_date          TEXT,
        external_uid        TEXT,
        external_source     TEXT    NOT NULL DEFAULT 'local',
        external_account_id INTEGER,
        points              INTEGER NOT NULL DEFAULT 0,
        visibility          TEXT    NOT NULL DEFAULT 'all',
        external_object_url TEXT,
        outbound_dirty      INTEGER NOT NULL DEFAULT 0,
        outbound_attempts   INTEGER NOT NULL DEFAULT 0
      , recurrence_origin_id INTEGER
        REFERENCES tasks(id) ON DELETE SET NULL, recurrence_from_completion INTEGER NOT NULL DEFAULT 0, archived_at TEXT, target_caldav_account_id INTEGER, target_caldav_list_url   TEXT, countdown INTEGER NOT NULL DEFAULT 0, locked INTEGER NOT NULL DEFAULT 0, recurrence_series_id INTEGER, sort_order INTEGER, seen_on_server INTEGER NOT NULL DEFAULT 0, rotation_mode TEXT
            CHECK (rotation_mode IS NULL OR rotation_mode IN ('round_robin')), rotation_last_user INTEGER REFERENCES users(id) ON DELETE SET NULL, rotation_last_position INTEGER, external_rrule TEXT);
CREATE INDEX idx_tasks_status     ON tasks(status);
CREATE INDEX idx_tasks_assigned   ON tasks(assigned_to);
CREATE INDEX idx_tasks_parent     ON tasks(parent_task_id);
CREATE INDEX idx_tasks_start_date ON tasks(start_date);
CREATE INDEX idx_tasks_external
        ON tasks(external_source, external_account_id, external_uid);
