        tag     TEXT    NOT NULL,
        tag_key TEXT    NOT NULL,
        PRIMARY KEY (item_id, tag_key)
      );
CREATE INDEX idx_shopping_item_tags_key ON shopping_item_tags(tag_key);
CREATE TABLE "recipe_provider_accounts" (
        id          INTEGER PRIMARY KEY AUTOINCREMENT,
        name        TEXT    NOT NULL,
        base_url    TEXT    NOT NULL,
        api_token   TEXT    NOT NULL,
        enabled     INTEGER NOT NULL DEFAULT 1,
        created_by  INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        last_sync   TEXT,
        last_error  TEXT, external_url TEXT, provider TEXT NOT NULL DEFAULT 'mealie'
        CHECK(provider IN ('mealie', 'tandoor')), last_error_reason TEXT, last_error_params TEXT,
        -- Eine Rezepttabelle je Mealie-Server: die UNIQUE-Bedingung verhindert,
        -- dass derselbe Server zweimal angelegt wird und alle Rezepte doppelt
        -- gespiegelt ankommen.
        UNIQUE(base_url)
      );
CREATE UNIQUE INDEX idx_recipes_mealie_unique
        ON recipes(provider_account_id, provider_recipe_id) WHERE provider_account_id IS NOT NULL;
CREATE TABLE invites (
        id               INTEGER PRIMARY KEY AUTOINCREMENT,
        token_hash       TEXT    NOT NULL,
        email            TEXT,
        username         TEXT,
        display_name     TEXT,
        role             TEXT    NOT NULL DEFAULT 'member'
                                 CHECK(role IN ('admin', 'member')),
        -- kein CHECK: FAMILY_ROLES wächst, eine append-only-Migration darf das
        -- nicht einfrieren. Validierung passiert in der Route.
        family_role      TEXT    NOT NULL DEFAULT 'other',
        created_by       INTEGER REFERENCES users(id) ON DELETE SET NULL,
        expires_at       INTEGER NOT NULL,
        accepted_at      TEXT,
        accepted_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
        revoked_at       TEXT,
        created_at       TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
      , permissions TEXT);
CREATE UNIQUE INDEX idx_invites_hash ON invites(token_hash);
CREATE INDEX idx_invites_open ON invites(expires_at)
        WHERE accepted_at IS NULL AND revoked_at IS NULL;
CREATE INDEX idx_tasks_recurrence_origin
        ON tasks(recurrence_origin_id) WHERE recurrence_origin_id IS NOT NULL;
