CREATE TABLE health_prevention_types (
        id                      INTEGER PRIMARY KEY AUTOINCREMENT,
        name                    TEXT    NOT NULL,
        kind                    TEXT    NOT NULL CHECK (kind IN ('vaccination', 'checkup')),
        default_interval_months INTEGER CHECK (default_interval_months IS NULL OR (default_interval_months BETWEEN 1 AND 600)),
        icon                    TEXT    NOT NULL DEFAULT 'syringe',
        sort_order              INTEGER NOT NULL DEFAULT 0,
        created_at              TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at              TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      );
CREATE TABLE health_prevention_records (
        id                   INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id              INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        type_id              INTEGER REFERENCES health_prevention_types(id) ON DELETE SET NULL,
        -- Momentaufnahme/Ausweich-Name: bleibt lesbar, wenn der Typ umbenannt
        -- oder geloescht wird (SET NULL oben) - Loeschen eines Typs darf seine
        -- Historie nicht mitreissen.
        name                 TEXT,
        given_on             TEXT    NOT NULL,
        dose_number          INTEGER,
        batch                TEXT,
        provider             TEXT,
        note                 TEXT,
        -- NULL = der Typ-Standard gilt; ein Wert hier ueberschreibt ihn nur
        -- fuer DIESEN Datensatz.
        interval_months      INTEGER CHECK (interval_months IS NULL OR (interval_months BETWEEN 1 AND 600)),
        -- Explizite Faelligkeit; NULL = aus given_on + Intervall abgeleitet
        -- (server/services/prevention-due.js, die einzige Stelle, die das rechnet).
        next_due_on          TEXT,
        -- NULL = Modul-Standard (30 Tage, DEFAULT_REMINDER_OFFSET_DAYS).
        reminder_offset_days INTEGER CHECK (reminder_offset_days IS NULL OR (reminder_offset_days BETWEEN 0 AND 365)),
        visibility           TEXT    NOT NULL CHECK (visibility IN ('private', 'family')),
        created_by           INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        created_at           TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at           TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      );
CREATE INDEX idx_health_prevention_records_user_date ON health_prevention_records(user_id, given_on);
CREATE TABLE recipe_ingredient_pantry_matches (
        recipe_id      INTEGER NOT NULL REFERENCES recipes(id) ON DELETE CASCADE,
        -- Normalisierter Zutatenname, siehe oben. Kein FK auf
        -- recipe_ingredients.id: genau die ID gibt es nach dem naechsten
        -- Speichern nicht mehr.
        ingredient_key TEXT    NOT NULL,
        -- ON DELETE CASCADE, und die Wahl ist nur in DIESER Tabelle die
        -- richtige. Das Schema nebenan setzt sonst ueberall SET NULL, wo die
        -- Zeile auch ohne ihr Gegenueber noch etwas bedeutet: meals.recipe_id
        -- (v13) laesst die Mahlzeit stehen, wenn das Rezept geht;
        -- pantry_items.location_id laesst den Bestand stehen, wenn der Lagerort
        -- geht; pantry_items.created_by wurde in v109 eigens von CASCADE auf
        -- SET NULL zurueckgebaut, weil ein geloeschtes Mitglied sonst den
        -- halben Vorrat mitgenommen haette. CASCADE steht dort, wo die Zeile
        -- NICHTS ausser der Verbindung ist - recipe_ingredients.recipe_id.
        --
        -- Diese Zeile ist nichts ausser der Verbindung. Ist die Vorratszeile
        -- weg, ist die Aussage des Haushalts gegenstandslos: sie galt dieser
        -- Packung, nicht einem Produkt (der Vorrat fuehrt bewusst Chargen, siehe
        -- Kommentar an pantry_items). Eine Zuordnung, die ins Leere zeigt, waere
        -- schlimmer als keine, und SET NULL liesse genau die stehen.
        --
        -- Und weil die Verbindung hier wohnt statt auf recipe_ingredients,
        -- reicht CASCADE nie bis zur Zutat: das Rezept behaelt sie, sie ist nur
        -- wieder unzugeordnet. Auf einer Spalte haette dieselbe Klausel die
        -- Zutat aus dem Rezept geloescht.
        pantry_item_id INTEGER NOT NULL REFERENCES pantry_items(id) ON DELETE CASCADE,
        -- Wer bestaetigt hat, als Herkunftsnachweis. SET NULL aus demselben
        -- Grund wie in v109: ein ausscheidendes Mitglied nimmt keine
        -- Haushaltsdaten mit.
        confirmed_by   INTEGER REFERENCES users(id) ON DELETE SET NULL,
        created_at     TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at     TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        -- Eine Zutat zeigt auf hoechstens eine Vorratszeile. Ein erneutes
        -- Bestaetigen ersetzt die alte Aussage, statt eine zweite danebenzulegen.
        PRIMARY KEY (recipe_id, ingredient_key)
      );
CREATE INDEX idx_ripm_pantry_item
        ON recipe_ingredient_pantry_matches(pantry_item_id);
CREATE TABLE health_nutrition_targets (
        user_id          INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
        energy_kcal      REAL CHECK (energy_kcal      IS NULL OR energy_kcal      >= 0),
        fat_g            REAL CHECK (fat_g            IS NULL OR fat_g            >= 0),
        saturated_fat_g  REAL CHECK (saturated_fat_g  IS NULL OR saturated_fat_g  >= 0),
        carbs_g          REAL CHECK (carbs_g          IS NULL OR carbs_g          >= 0),
        sugar_g          REAL CHECK (sugar_g          IS NULL OR sugar_g          >= 0),
        protein_g        REAL CHECK (protein_g        IS NULL OR protein_g        >= 0),
        salt_g           REAL CHECK (salt_g           IS NULL OR salt_g           >= 0),
        fiber_g          REAL CHECK (fiber_g          IS NULL OR fiber_g          >= 0),
        created_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      );
CREATE TABLE health_nutrition_entries (
        id              INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id         INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        -- Wanduhrzeit des Haushalts (YYYY-MM-DDTHH:mm), kein Instant: "heute"
        -- ist hier ein Kalendertag, und der faellt in der Haushaltszone
        -- (server/utils/timezone.js, todayKey). Ein UTC-Zeitpunkt haette am
        -- Abend westlich und am Morgen oestlich von UTC den Nachbartag
        -- getragen.
        consumed_at     TEXT    NOT NULL,
        meal_type       TEXT    CHECK (meal_type IS NULL OR meal_type IN ('breakfast', 'lunch', 'dinner', 'snack')),
        title           TEXT    NOT NULL,
        energy_kcal     REAL CHECK (energy_kcal     IS NULL OR energy_kcal     >= 0),
        fat_g           REAL CHECK (fat_g           IS NULL OR fat_g           >= 0),
        saturated_fat_g REAL CHECK (saturated_fat_g IS NULL OR saturated_fat_g >= 0),
        carbs_g         REAL CHECK (carbs_g         IS NULL OR carbs_g         >= 0),
        sugar_g         REAL CHECK (sugar_g         IS NULL OR sugar_g         >= 0),
        protein_g       REAL CHECK (protein_g       IS NULL OR protein_g       >= 0),
        salt_g          REAL CHECK (salt_g          IS NULL OR salt_g          >= 0),
        fiber_g         REAL CHECK (fiber_g         IS NULL OR fiber_g         >= 0),
        note            TEXT,
        -- DAS KANONISCHE VOKABULAR AUS docs/DECISIONS.md ABSCHNITT 5, nicht das
        -- Paar private/family, das die Gesundheit sonst fuehrt. Abschnitt 5
        -- nennt dieses Paar unter den Vokabularen, die er normalisieren will,
        -- und haelt einen neuen Gesundheits-Tab, der mit einer eigenen Spalte
        -- in ebendiesem Paar ankam (PR #1019), als den Fall fest, den er
        -- verhindern soll. "Neue Module nehmen den kanonischen Satz von
        -- Anfang an" ist der Satz, und ein Tagebuch je Person ist das
        -- Zeilenaufkommen eines neuen Moduls.
        --
        -- Der benannte Satz aus der Mitte des Vokabulars ('assignees') steht
        -- bewusst NICHT im CHECK: die Gesundheit hat keine Zuweisungstabelle,
        -- der Wert waere hier von 'private' nicht unterscheidbar und damit ein
        -- Wert, der etwas anderes behauptet, als er tut. Er kommt, wenn es
        -- eine Zuordnung gibt, die ihn traegt.
        visibility      TEXT    NOT NULL DEFAULT 'private' CHECK (visibility IN ('private', 'all')),
        created_by      INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        created_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
      );
CREATE INDEX idx_health_nutrition_entries_user_date
        ON health_nutrition_entries(user_id, consumed_at);
