        AFTER UPDATE ON calendar_events FOR EACH ROW
        BEGIN UPDATE calendar_events SET updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = OLD.id; END;
CREATE TRIGGER trg_event_local_calendar_insert
      BEFORE INSERT ON calendar_events
      WHEN NEW.local_calendar_id IS NOT NULL AND (NEW.external_source IS NOT 'local'
        OR NEW.target_google_calendar_id IS NOT NULL OR NEW.target_caldav_account_id IS NOT NULL)
      BEGIN SELECT RAISE(ABORT, 'Local and sync calendars are mutually exclusive'); END;
CREATE TRIGGER trg_event_local_calendar_update
      BEFORE UPDATE OF local_calendar_id, external_source, target_google_calendar_id, target_caldav_account_id ON calendar_events
      WHEN NEW.local_calendar_id IS NOT NULL AND (NEW.external_source IS NOT 'local'
        OR NEW.target_google_calendar_id IS NOT NULL OR NEW.target_caldav_account_id IS NOT NULL)
      BEGIN SELECT RAISE(ABORT, 'Local and sync calendars are mutually exclusive'); END;
CREATE TRIGGER trg_users_avatar_key_update
        AFTER UPDATE OF avatar_data ON users FOR EACH ROW
        WHEN NEW.avatar_data IS NOT OLD.avatar_data
        BEGIN
          UPDATE users SET avatar_key = CASE
            WHEN NEW.avatar_data IS NULL OR NEW.avatar_data = '' THEN NULL
            ELSE lower(hex(randomblob(16))) END
          WHERE id = OLD.id;
        END;
CREATE TRIGGER trg_users_avatar_key_insert
        AFTER INSERT ON users FOR EACH ROW
        WHEN NEW.avatar_data IS NOT NULL AND NEW.avatar_data <> ''
        BEGIN UPDATE users SET avatar_key = lower(hex(randomblob(16))) WHERE id = NEW.id; END;
CREATE TRIGGER trg_reminders_tasks_ad
      AFTER DELETE ON tasks BEGIN
        DELETE FROM reminders WHERE entity_type = 'task' AND entity_id = OLD.id;
      END;
